/*
 * A257980  Sequence (d(n)) generated by Rule 3 (in Comments) with a(1) = 0
 *          and d(1) = 3.
 * https://oeis.org/A257980
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  easy, sign
 * Formula:   not stated
 * Range:     i8 n <= 165, i16 n <= 1000, i32 n <= 1000, i64 n <= 1000,
 *            i128 n <= 1000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Simulates Rule 3 for OEIS sequence A257980 (the d‐sequence). */
/* Returns d(n) where a(1)=0, d(1)=3 and the rule is applied as described. */
#include <stdlib.h>
#include <stdbool.h>

/* linear search – works for the small n considered.  */
static bool contains(const seq_t *arr, size_t len, seq_t v)
{
    for (size_t i = 0; i < len; ++i)
        if (arr[i] == v) return true;
    return false;
}

/* extend the storage to hold at least `need` elements.  */
static void grow_to(size_t need, seq_t **A, seq_t **D, size_t *cap)
{
    if (*cap >= need) return;
    size_t new_cap = *cap ? *cap << 1 : 8;
    while (new_cap < need) new_cap <<= 1;
    *A = (seq_t *)realloc(*A, new_cap * sizeof(seq_t));
    *D = (seq_t *)realloc(*D, new_cap * sizeof(seq_t));
    if (!*A || !*D) abort();          /* allocation failure */
    *cap = new_cap;
}

/* seq_t a(idx_t n)  →  d(n)  for sequence A257980 */
seq_t a(idx_t n)
{
    static seq_t *A = NULL, *D = NULL;
    static size_t cap = 0, len = 0;   /* number of computed entries */

    /* ensure space for the requested index */
    grow_to((size_t)n, &A, &D, &cap);

    /* generate sequence up to n */
    while (len < (size_t)n)
    {
        if (len == 0)          /* initial values for k=1 */
        {
            A[0] = (seq_t)0;
            D[0] = (seq_t)3;
            len = 1;
            continue;
        }

        seq_t ak = A[len-1];

        /* Step 1: look for a negative h with 1‑ak < h < 0. */
        seq_t h_start = (seq_t)2 - ak;          /* smallest integer > 1‑ak */
        bool found = false;
        for (seq_t h = h_start; h <= -(seq_t)1; ++h)
        {
            if (contains(D, len, h)) continue;
            seq_t new_a = ak + h;
            if (contains(A, len, new_a)) continue;
            A[len] = new_a;
            D[len] = h;
            ++len;
            found = true;
            break;
        }
        if (found) continue;

        /* Step 2: find the least positive h not in D(k) such that ak‑h not in A(k). */
        seq_t h = 1;
        while (true)
        {
            if (!contains(D, len, h) && !contains(A, len, ak - h))
            {
                A[len] = ak + h;
                D[len] = h;
                ++len;
                break;
            }
            ++h;
        }
    }

    return D[(size_t)n-1];
}
